using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckSkyTow {
public sealed class SkyTowRacer:MonoBehaviour {
 public SkyTowMatch match;public SportsEventTruck truck;public Rigidbody boat;public ConfigurableJoint tether;public LineRenderer cable;public Transform propeller;public int slot;public float ropeLength=35,controlAcceleration=3.2f,liftControlRange=.9f,maximumLift=16;public bool Failed{get;private set;}public string Reaction{get;private set;}="READY";public int RingContacts{get;private set;}
 Quaternion previousRotation;Vector3 previous;bool[] touched=new bool[36];float cruise;public Vector2 LastControl{get;private set;}public float LastLift{get;private set;}public float LastAirspeed{get;private set;}public float FurthestCable{get;private set;}
 public void Prepare(){Failed=false;RingContacts=0;FurthestCable=0;System.Array.Clear(touched,0,touched.Length);match.course.Frame(0,slot,out var point,out var rotation);boat.position=point;boat.rotation=rotation;truck.Prepare(point+rotation*new Vector3(0,18,-29),rotation,false);truck.body.isKinematic=true;tether.connectedBody=boat;Connect(true);previous=truck.body.position;previousRotation=truck.body.rotation;cruise=match.course.length/match.course.duration;Reaction="READY";}
 public void Release(){truck.body.isKinematic=false;truck.body.linearVelocity=boat.rotation*Vector3.forward*cruise;truck.body.angularVelocity=Vector3.zero;previous=truck.body.position;previousRotation=truck.body.rotation;}
 public void Step(float age,Vector2 command,float dt){if(Failed||match.rules.finished[slot])return;match.course.Frame(age,slot,out var point,out var rotation);boat.MovePosition(point);boat.MoveRotation(rotation);var body=truck.body;var forward=rotation*Vector3.forward;var right=rotation*Vector3.right;Vector3 relative=body.linearVelocity-match.atmosphere.Flow;float airspeed=Vector3.ProjectOnPlane(relative,Vector3.up).magnitude;float lift=SkyTowAero.Acceleration(airspeed,match.course.Cruise,command.y,Physics.gravity.magnitude,maximumLift,liftControlRange);LastControl=command;LastLift=lift;LastAirspeed=airspeed;body.AddForce(Vector3.up*lift+right*(command.x*controlAcceleration),ForceMode.Acceleration);body.AddForce(Vector3.ClampMagnitude((match.atmosphere.Flow-body.linearVelocity)*.015f,1),ForceMode.Acceleration);var desired=rotation*Quaternion.Euler(-command.y*15,0,-command.x*24);var delta=desired*Quaternion.Inverse(body.rotation);delta.ToAngleAxis(out float angle,out Vector3 axis);if(angle>180)angle-=360;if(!float.IsNaN(axis.x))body.AddTorque(Vector3.ClampMagnitude(axis*angle*.08f-body.angularVelocity*2,6),ForceMode.Acceleration);if(body.position.y>38&&body.linearVelocity.y>0)body.AddForce(Vector3.down*Mathf.Min(6,(body.position.y-38)*.6f),ForceMode.Acceleration);
  FurthestCable=Mathf.Max(FurthestCable,Vector3.Distance(body.position,boat.position));for(int i=0;i<36;i++){if(match.rules.outcomes[slot,i]!=0)continue;var ring=match.course.Ring(slot,i);var normal=ring.transform.forward;var scale=truck.transform.lossyScale;var localCenter=Vector3.Scale(truck.shape.center,scale);var beforeCenter=previous+previousRotation*localCenter;var nowCenter=body.position+body.rotation*localCenter;float before=Vector3.Dot(beforeCenter-ring.transform.position,normal)-NormalExtent(previousRotation,normal),after=Vector3.Dot(nowCenter-ring.transform.position,normal)-NormalExtent(body.rotation,normal);if(before<0&&after>=0){float t=Mathf.Clamp01(-before/(after-before));var crossing=Vector3.Lerp(beforeCenter,nowCenter,t);float radial=Vector3.ProjectOnPlane(crossing-ring.transform.position,normal).magnitude;if(i<3)Debug.Log("SKYTOW_RING slot="+slot+" index="+i+" age="+age+" p="+body.position+" ring="+ring.transform.position+" radial="+radial+" touched="+touched[i]+" wind="+match.atmosphere.Flow+" airspeed="+airspeed+" lift="+lift);bool through=SkyTowRules.SweptOpening(before,after,radial,ring.ClearRadius,Mathf.Max(PlaneRadius(previousRotation,normal),PlaneRadius(body.rotation,normal)),touched[i]);if(match.rules.Ring(slot,i,through,ring.bonus,radial<.85f)){ring.Tint(through);Reaction=through?(ring.bonus?"GOLD RING!":"CLEAN RING!"):"MISSED RING";match.RingResolved(slot,through,ring.bonus);}}else if(age>ring.at+7){match.rules.Ring(slot,i,false,ring.bonus,false);ring.Tint(false);}}
  previous=body.position;previousRotation=body.rotation;if(body.position.y<.6f||body.position.y>65||Vector3.Distance(body.position,boat.position)>ropeLength+5){Failed=true;Reaction="SPLASHDOWN · RUN COMPLETE";Connect(false);match.rules.Finish(slot);match.feedback.Play(3,0,true);match.Pulse(slot,.45f,.15f);}else if(age>=match.course.LaneDuration(slot)){Reaction="ARCTIC RUN COMPLETE";match.rules.Finish(slot);}
 }
 float NormalExtent(Quaternion rotation,Vector3 normal){var e=Vector3.Scale(truck.shape.size*.5f,truck.transform.lossyScale);return Mathf.Abs(Vector3.Dot(rotation*Vector3.right,normal))*e.x+Mathf.Abs(Vector3.Dot(rotation*Vector3.up,normal))*e.y+Mathf.Abs(Vector3.Dot(rotation*Vector3.forward,normal))*e.z;}
 float PlaneRadius(Quaternion rotation,Vector3 normal){var e=Vector3.Scale(truck.shape.size*.5f,truck.transform.lossyScale);float radius=0;for(int i=0;i<8;i++){var corner=rotation*Vector3.Scale(e,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));radius=Mathf.Max(radius,Vector3.ProjectOnPlane(corner,normal).magnitude);}return radius;}
 public void Present(){if(cable!=null){cable.SetPosition(0,boat.transform.TransformPoint(new Vector3(0,1,-1)));cable.SetPosition(1,truck.transform.TransformPoint(new Vector3(0,1.25f,.2f)));}if(propeller!=null&&match.Live)propeller.Rotate(Vector3.forward,Time.deltaTime*1800,Space.Self);}
 void OnCollisionEnter(Collision collision){var ring=collision.collider.GetComponentInParent<SkyTowRing>();if(ring!=null&&ring.slot==slot&&ring.index>=0&&ring.index<touched.Length){touched[ring.index]=true;RingContacts++;if(match.rules.Ring(slot,ring.index,false,ring.bonus,false))ring.Tint(false);Debug.Log("SKYTOW_RIM slot="+slot+" ring="+ring.index+" p="+truck.body.position+" velocity="+truck.body.linearVelocity+" relative="+collision.relativeVelocity+" hull="+truck.shape.bounds+" contact="+collision.GetContact(0).point+" normal="+collision.GetContact(0).normal);}if(match.Live&&collision.relativeVelocity.magnitude>3){match.feedback.Play(1,collision.relativeVelocity.magnitude);match.Pulse(slot,.12f,.07f);}}
 void Connect(bool attached){tether.xMotion=tether.yMotion=tether.zMotion=attached?ConfigurableJointMotion.Limited:ConfigurableJointMotion.Free;}
 public void Stop(){Connect(false);truck.Power(false);if(!truck.body.isKinematic)truck.body.linearVelocity=truck.body.angularVelocity=Vector3.zero;truck.body.isKinematic=true;}
}
}
